def _basis(t, traj):
    from scipy.optimize import least_squares

    def basis(k):
        return -np.expm1(-t[:, None] * k)

    def err(k):
        B = basis(k)
        return (B @ _ls(B, traj.T) - traj.T).ravel()
    rates = least_squares(err, [1.8, 0.4], bounds=([0.8, 0.03], [8.0, 0.79])).x
    return basis(rates)

def _design(x, kind):
    (i, j) = np.triu_indices(x.shape[1])
    s = {'rat': lambda q: q / (1 + q * q), 'tanh': np.tanh, 'gauss': lambda q: q * np.exp(-q * q)}[kind](x)
    return np.column_stack((np.ones(len(x)), x, x[:, i] * x[:, j], s, (x[:, :, None] * s[:, None, :]).reshape(len(x), x.shape[1] ** 2)))

def _predict(x, q, target, kind, penalty):
    (f, g) = (_design(x, kind), _design(q, kind))
    reg = np.eye(f.shape[1]) * np.sqrt(penalty)
    return g @ _ls(np.r_[f, reg], np.r_[target, np.zeros((len(reg), target.shape[1]))])
